class CoreGallery{gallery=null;constructor(sectionId,view){this.sectionId=sectionId;this.slider=null;this.sliderElement=document.querySelector(`#slider-${sectionId}`);this.sectionElement=document.querySelector(`#section-gallery-${sectionId}`);this.tagMain=this.sectionElement.querySelector(".core-gallery__nav__selected-tag");this.savedHeight=null;this.currentView=view;this.isMobile=window.matchMedia("(max-width: 1024px)").matches;this.initSlider();this.initTabs();this.initSwitcher();this.initResponsiveSelect()}
getSliderConfig(view){let config={selector:".core-gallery__content__item",mode:"free",renderMode:"precision",};if(view==="grid-2x2"){config.slides={perView:2,spacing:16,};config.selector=".core-gallery__content__item";config.breakpoints={"(max-width: 576px)":{slides:{perView:2,spacing:8,},},}}else if(view==="grid-1x1"){config.slides={perView:"auto",spacing:16,};if(this.isMobile){config.selector=".core-gallery__content__item"}else{config.selector=".core-gallery__content__item__image"}
config.breakpoints={"(max-width: 768px)":{slides:{perView:0.5,spacing:8,},},}}else if(view==="grid-2x1"){config.slides={perView:0.5,spacing:16,};config.selector=".core-gallery__content__item"}
return config}
initSlider(){const sliderConfig=this.getSliderConfig(this.currentView);this.slider=new KeenSlider(this.sliderElement,sliderConfig);this.ligthbox();if(!this.savedHeight&&this.currentView==="grid-2x2"){setTimeout(()=>{this.savedHeight=this.sliderElement.offsetHeight},2000)}else{this.updateImageUrls(this.currentView)}}
initTabs(){const tabs=this.sectionElement.querySelectorAll(`.core-gallery__nav__tags-item`);tabs.forEach((tab)=>{tab.addEventListener("click",(event)=>{event.preventDefault();this.handleTabClick(tab)})})}
initSwitcher(){const switchers=this.sectionElement.querySelectorAll(`.view-option`);switchers.forEach((switcher)=>{switcher.addEventListener("click",()=>this.handleSwitcherClick(switcher))})}
initResponsiveSelect(){if(!this.isMobile)return;const tagsList=this.sectionElement.querySelector(".core-gallery__nav__tags");const arrow=this.tagMain.querySelector(".core-gallery__nav__selected-tag__arrow");this.tagMain.addEventListener("click",()=>{const isOpen=tagsList.classList.contains("core-gallery__nav__tags--open");tagsList.classList.toggle("core-gallery__nav__tags--open",!isOpen);arrow.classList.toggle("arrow-rotate",!isOpen)});tagsList.querySelectorAll(".core-gallery__nav__tags-item").forEach(item=>{item.addEventListener("click",()=>{const label=item.getAttribute("data-label");this.tagMain.querySelector(".core-gallery__nav__selected-tag__text").textContent=label;tagsList.classList.remove("core-gallery__nav__tags--open");arrow.classList.remove("arrow-rotate")})});document.addEventListener("click",(e)=>{if(!this.sectionElement.contains(e.target)){tagsList.classList.remove("core-gallery__nav__tags--open");arrow.classList.remove("arrow-rotate")}})}
showModal(){this.modalOverlay.classList.remove("hidden")}
hideModal(){this.modalOverlay.classList.add("hidden")}
ligthbox(){if(this.gallery){this.gallery.destroy()}
const options={plugins:[lgZoom,lgThumbnail],selector:'.core-gallery__content__item__image',showCloseIcon:!0,loop:!1,mobileSettings:{showCloseIcon:!0}}
this.gallery=lightGallery(this.sectionElement,options)}
handleTabClick(tab){const value=tab.getAttribute("data-value");const id=tab.getAttribute("data-id");const label=tab.getAttribute("data-label");document.querySelectorAll(".core-gallery__nav__tags-item").forEach((item)=>item.classList.remove("active"));tab.classList.add("active");if(this.isMobile){this.tagMain.querySelector(".core-gallery__nav__selected-tag__text").innerHTML=label};this.loadTabContent(value)}
handleSwitcherClick(option){const value=option.getAttribute("data-view");this.sectionElement.querySelectorAll(`.view-option`).forEach((item)=>item.classList.remove("active"));option.classList.add("active");this.currentView=value;const items=this.sliderElement.querySelectorAll(".core-gallery__content__item");items.forEach((item)=>{item.classList.remove("grid-2x2","grid-2x1","grid-1x1");item.classList.add(value)});this.updateImageUrls(value);if(this.slider){this.slider.destroy()}
const contentContainer=document.querySelector(`#slider-${this.sectionId}`);const slides=contentContainer.querySelectorAll(".core-gallery__content__item");contentContainer.innerHTML="";contentContainer.append(...slides);this.initSlider()}
updateImageUrls(view){const images=this.sliderElement.querySelectorAll("img");images.forEach((img)=>{let src=img.getAttribute("src");if(view==="grid-2x2"){src=src.replace(/w=\d+&h=\d+/,"w=500&h=500");src=src.replace(/w=auto&h=\d+/,"w=500&h=500");img.style.height="inherit"}else if(view==="grid-1x1"){src=src.replace(/w=\d+&h=\d+/,"w=auto&h=950");let newHeight=this.savedHeight?this.savedHeight+"px":'45.5vw';img.style.height=newHeight}else if(view==="grid-2x1"){src=src.replace(/w=\d+&h=\d+/,"w=950&h=950");src=src.replace(/w=auto&h=\d+/,"w=950&h=950");img.style.height="inherit"}
img.setAttribute("src",src)})}
loadTabContent(value){const ajaxUrl=document.querySelector(`#section-gallery-${this.sectionId} .core-gallery__nav__tags`).getAttribute("data-ajax-url");const spinnerOverlay=this.sectionElement.querySelector(".core-gallery__spinner-overlay");if(spinnerOverlay)spinnerOverlay.style.display="flex";fetch(`${ajaxUrl}&id=${this.sectionId}&tab=${value}&class=${this.currentView}`).then((response)=>response.json()).then((data)=>{if(data.success){const contentContainer=document.querySelector(`#slider-${this.sectionId}`);const responseHtml=document.createElement("div");responseHtml.innerHTML=data.data.gallery;const slides=responseHtml.querySelectorAll(".core-gallery__content__item");contentContainer.innerHTML="";contentContainer.append(...slides);this.updateImageUrls(this.currentView);if(this.slider){this.slider.destroy()}
this.initSlider()}else{console.error("Error: ",data.data.message)}
if(spinnerOverlay)spinnerOverlay.style.display="none"}).catch((error)=>{console.error("Error fetching tab content:",error);if(spinnerOverlay)spinnerOverlay.style.display="none"})}}